def replaces_in_file(file, replacement_list):
    rs = [(re.compile(regexp), repl) for (regexp, repl) in replacement_list]
    file_tmp = file + "." + str(os.getpid()) + ".tmp"
    with open(file, 'r') as f:
        with open(file_tmp, 'w') as f_tmp:
            for line in f:
                for r, replace in rs:
                    match = r.search(line)
                    if match:
                        line = replace + "\n"
                f_tmp.write(line)
    shutil.move(file_tmp, file)

def replace_doc_text(file, replacements):
    document = Document(file)
    paragraphs = document.paragraphs

    changes = False

    for paragraph in paragraphs:
        text = paragraph.text
        for original, replace in replacements.items():
            if original in replace and replace in text:
                continue
            if original in text:
                changes = True
                text = text.replace(original, replace)
                paragraph.text = text

    if changes:
        print("changing {}".format(file))

    document.save(file)

