def handle_http_error(self, response, custom_messages=None,
                          raise_for_status=False):
        if not custom_messages:
            custom_messages = {}
        if response.status_code in custom_messages.keys():
            raise requests.exceptions.HTTPError(
                custom_messages[response.status_code])
        if raise_for_status:
            response.raise_for_status()

def handle_http_error(
        self, response, ignore=None, custom_messages=None, raise_for_status=True
    ):
        status = response.status_code
        ignore = ignore or []
        custom_messages = custom_messages or {}

        if status in ignore or status in self._ignore_codes:
            return None
        elif response.status_code in custom_messages.keys():
            raise requests.exceptions.HTTPError(custom_messages[response.status_code])
        elif raise_for_status:
            response.raise_for_status()

def raise_for_status(self, response):
        http_error_msg = ''

        if 400 <= response.status_code < 500:
            try:
                http_error_msg = response.json()
            except:
                http_error_msg = ('{code} Client Error: {reason} for url: {url}'.format(
                    code=response.status_code, reason=response.reason, url=response.url)
                )

        elif 500 <= response.status_code < 600:
            http_error_msg = ('{code} Server Error: {reason} for url: {url}'.format(
                code=response.status_code, reason=response.reason, url=response.url)
            )

        if http_error_msg:
            raise HTTPError(http_error_msg, response=response)

