static public function display(string $view = null, array $params = []): string
    {
        // 是否是被嵌套,默认是否
        static $nested = false;

        // 如果有模板变量,解开
        if ($params and count($params)) {
            extract($params);
        }

        // 如果是被嵌套,直接包含就是了
        if ($nested) {
            include(self::getTpl($view));
            return '';
        }

        // 当前是被嵌套
        $nested = 1;

        // 引入模版文件
        include(self::getTpl($view));

        // 嵌套结束了
        $nested = 0;

        return '';
    }

