private static function convertString(string $value): string
    {
        if ($value === '') {
            return '';
        }

        if ($value[0] === '"') {
            $value = \mb_substr($value, 1, -1);
        }

        return \strtr(
            $value,
            [
                '\\\\' => '\\',
                '\\a'  => "\x07",
                '\\b'  => "\x08",
                '\\t'  => "\t",
                '\\n'  => "\n",
                '\\v'  => "\x0b",
                '\\f'  => "\x0c",
                '\\r'  => "\r",
                '\\"'  => '"',
            ]
        );
    }

protected function resolveOne($middleware, &$key = null)
    {
        if ($middleware instanceof Closure) {
            $key = $key ? $this->castKey($key) : "";

        } elseif ($this->isAbstract($middleware)) {
            $key = $this->castKey($key, $middleware);
            $middleware = new $middleware;

        } elseif (is_object($middleware) && $middleware instanceof MiddlewareInterface) {
            $key = $this->castKey($key, get_class($middleware));

        } elseif (is_callable($middleware)) {
            $key = $key ? $this->castKey($key) : "";

        } elseif ($middleware instanceof MiddlewareCollection) {
            $key = $middleware->getId();
            $middleware = $this->resolveMany($middleware, $middleware->getId());

        } else {
            $middleware = false;
        }
        return $middleware;
    }

